import "dotenv/config";
import prisma from "./client"
import { departmentsSeedData, roleSeedData } from "./seedData";

async function main() {
    
    // clear tables
    await prisma.employee.deleteMany();
    await prisma.department.deleteMany();
    await prisma.role.deleteMany();
    
    // create each dpet, then its employee
    for (const department of departmentsSeedData) {
        // create department with name, id will be auto-generated by db
        const createdDepartment = await prisma.department.create({
            data: {
                name: department.name
            }
        });
        // create multiple employees for the department, with departmentId
        await prisma.employee.createMany({
            data: department.employees.map((employee) => ({
                ...employee, departmentId: createdDepartment.id
            }))
        });
    }

    // create each role
    for (const role of roleSeedData) {
        // create role, if employeeId is not provided, set it to null. (employee is optional)
        let employeeId: string | undefined;

        // if employee is provided, create employee and get its id
        if ( role.employee ) {
            const newEmployee = await prisma.employee.create({ data: role.employee });
            employeeId = newEmployee.id;
        }

        // create role with title and employeeId (if provided)s
        await prisma.role.create({
            data: { title: role.title, employeeId }
        });
    }
};

main().then(
    async() => {
        await prisma.$disconnect()
    }
).catch(async (e) => {
    console.error(e);
    await prisma.$disconnect();
    process.exit(1);
}); 